tool_input.command:
cd 'D:\repository\门户'
$env:NODE_OPTIONS='--max-old-space-size=4096'
npm run build --workspace=zhi2-web-admin 2>&1 | Select-String -Pattern 'error' | Select-Object -Last 3
echo "EXIT: $LASTEXITCODE"
node -e "
const {chromium}=require('playwright');
(async()=>{const b=await chromium.launch();const p=await b.newContext({viewport:{width:1920,height:1080}}).then(c=>c.newPage());
await p.goto('http://127.0.0.1:8092/index.html#/market-monitor',{waitUntil:'domcontentloaded'});await p.waitForSelector('.mm-dashboard',{timeout:20000});await p.waitForTimeout(1000);
const cb=p.locator('.el-message-box__wrapper .el-button').filter({hasText:'关闭'}).first();if(await cb.count())await cb.click({timeout:3000}).catch(()=>{});
const bg=await p.evaluate(()=>{const el=document.querySelector('.mm-dashboard header .rounded-lg.flex.items-center');return el?getComputedStyle(el).backgroundColor:'none';});
console.log('logo container bg:', bg);
await p.screenshot({path:'.workbuddy/logo-transparent.png',clip:{x:0,y:0,width:700,height:64}});
await b.close();})();
"
